        if (source.getEntity() != null && source.getDirectEntity() instanceof CavebloomerBombEntity bomb) {
            if (!level().isClientSide) bomb.discard(); return false;
        }
        return !source.is(DamageTypes.FALL) && super.hurt(source, amount);
    }

