        super.addAdditionalSaveData(tag); tag.putString("Texture", texture()); tag.putBoolean("PylonActivated", activated); tag.putBoolean("PylonDeathVisualStarted", deathVisualStarted);
        tag.putBoolean("PylonExperiencePending", experiencePending); if (experienceAttacker != null) tag.putUUID("PylonExperienceAttacker", experienceAttacker);
    }

@Override public void readAdditionalSaveData(CompoundTag tag) {
        super.readAdditionalSaveData(tag); if (tag.contains("Texture")) setTexture(tag.getString("Texture"));
        if (!tag.contains("NeoForgeData", 10) && tag.contains("ForgeData", 10)) getPersistentData().merge(tag.getCompound("ForgeData"));
        activated = tag.getBoolean("PylonActivated"); deathVisualStarted = tag.getBoolean("PylonDeathVisualStarted"); experiencePending = tag.getBoolean("PylonExperiencePending");
        experienceAttacker = tag.hasUUID("PylonExperienceAttacker") ? tag.getUUID("PylonExperienceAttacker") : null;
