public final class LautEntity extends PathfinderMob implements GeoEntity {
    private static final EntityDataAccessor<Boolean> COMPLETED = SynchedEntityData.defineId(LautEntity.class, EntityDataSerializers.BOOLEAN);
    private static final EntityDataAccessor<String> TEXTURE = SynchedEntityData.defineId(LautEntity.class, EntityDataSerializers.STRING);
    private final AnimatableInstanceCache animations = GeckoLibUtil.createInstanceCache(this);
    public LautEntity(EntityType<? extends LautEntity> type, Level level) { super(type, level); xpReward = 0; setCustomName(Component.literal("§aLaut")); setCustomNameVisible(true); setPersistenceRequired(); }
    public static AttributeSupplier.Builder createAttributes() { return Mob.createMobAttributes().add(Attributes.MAX_HEALTH, 75).add(Attributes.ARMOR, 30).add(Attributes.MOVEMENT_SPEED, 0).add(Attributes.ATTACK_DAMAGE, 0).add(Attributes.FOLLOW_RANGE, 16).add(Attributes.KNOCKBACK_RESISTANCE, 1).add(Attributes.STEP_HEIGHT, 0); }
    @Override protected void defineSynchedData(SynchedEntityData.Builder builder) { super.defineSynchedData(builder); builder.define(COMPLETED, false); builder.define(TEXTURE, "laut"); }
    @Override protected void registerGoals() { }
    public boolean completed() { return entityData.get(COMPLETED); }
    public String texture() { return entityData.get(TEXTURE); }
    boolean claim() { if (completed() || !isAlive()) return false; entityData.set(COMPLETED, true); getPersistentData().putBoolean("hasplenkys", true); return true; }
    void release() { entityData.set(COMPLETED, false); getPersistentData().putBoolean("hasplenkys", false); }
    @Override public boolean removeWhenFarAway(double distance) { return false; }
    @Override public boolean hurt(DamageSource source, float amount) {
        if (source.getDirectEntity() instanceof AbstractArrow || source.getDirectEntity() instanceof ThrownPotion || source.getDirectEntity() instanceof AreaEffectCloud) return false;
        if (source.is(DamageTypes.IN_FIRE) || source.is(DamageTypes.FALL) || source.is(DamageTypes.CACTUS) || source.is(DamageTypes.DROWN) || source.is(DamageTypes.LIGHTNING_BOLT) || source.is(DamageTypes.EXPLOSION) || source.is(DamageTypes.TRIDENT) || source.is(DamageTypes.FALLING_ANVIL) || source.is(DamageTypes.DRAGON_BREATH) || source.is(DamageTypes.WITHER) || source.is(DamageTypes.WITHER_SKULL)) return false;
        return super.hurt(source, amount);
    }
    @Override protected InteractionResult mobInteract(Player player, InteractionHand hand) {
        super.mobInteract(player, hand);
        if (!completed() && player instanceof ServerPlayer serverPlayer) LautContent.open(serverPlayer, this, blockPosition(), LautQuest.available(serverPlayer) >= 3 ? LautPage.HAVE : LautPage.NEED);
        return InteractionResult.sidedSuccess(level().isClientSide);
    }
    @Override protected void tickDeath() { if (++deathTime >= 20) remove(RemovalReason.KILLED); }
    @Override public void addAdditionalSaveData(CompoundTag tag) { super.addAdditionalSaveData(tag); tag.putString("Texture", texture()); tag.putBoolean("LautHasPlenkys", completed()); }
    @Override public void readAdditionalSaveData(CompoundTag tag) {
        super.readAdditionalSaveData(tag);
        if (!tag.contains("NeoForgeData", 10) && tag.contains("ForgeData", 10)) getPersistentData().merge(tag.getCompound("ForgeData"));
        if (tag.contains("Texture")) entityData.set(TEXTURE, tag.getString("Texture"));
        entityData.set(COMPLETED, tag.getBoolean("LautHasPlenkys") || getPersistentData().getBoolean("hasplenkys"));
        setPersistenceRequired();
    }
    @Override public void registerControllers(AnimatableManager.ControllerRegistrar controllers) { controllers.add(new AnimationController<>(this, "movement", 4, state -> state.setAndContinue(RawAnimation.begin().thenLoop(completed() ? "1" : "0")))); }
    @Override public AnimatableInstanceCache getAnimatableInstanceCache() { return animations; }
}

